import React, { useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Card,
  CardContent,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControl,
  InputLabel,
  MenuItem,
  Select,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ShareIcon from '@mui/icons-material/Share';
import ScheduleIcon from '@mui/icons-material/Schedule';
import DeleteOutlineIcon from '@mui/icons-material/DeleteOutline';
import PersonAddAltIcon from '@mui/icons-material/PersonAddAlt';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import ApiService from '../../services/api';
import { useSupplierCarbonScoresQuery } from '../../hooks/queries/usePlatformQueries';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { queryKeys } from '../../constants/queryKeys';
import useAppTranslation from '../../hooks/useAppTranslation';

type SupplierScoreRow = {
  vendor: string;
  scoreBand: string;
  intensityKgCo2ePerInr: number;
  tier1DataRatio: number;
  recommendation?: string;
  enrollmentStatus?: string;
  supplierProfileId?: string | null;
  contactEmail?: string | null;
  canInvite?: boolean;
};

type SupplierScoresPayload = {
  suppliers?: SupplierScoreRow[];
  enrolledCount?: number;
  invitedCount?: number;
  summary?: {
    supplierCount?: number;
    tier1CoveragePct?: number;
  };
};

type ScheduledReportRow = {
  _id: string;
  reportType?: string;
  format?: string;
  frequency?: string;
  recipients?: string[];
  enabled?: boolean;
  nextRunAt?: string;
  lastRunAt?: string;
  lastStatus?: string;
};

export type ReportingPlatformPanelProps = {
  period?: string;
  reportType?: string;
  readinessLevel?: string | null;
  totalKgCo2e?: number;
};

const enrollmentChipColor = (status?: string): 'default' | 'warning' | 'success' | 'info' => {
  if (status === 'enrolled' || status === 'verified') return 'success';
  if (status === 'invited' || status === 'requested') return 'warning';
  if (status === 'responded') return 'info';
  return 'default';
};

const ReportingPlatformPanel: React.FC<ReportingPlatformPanelProps> = ({
  period = 'annual',
  reportType = 'brsr',
  readinessLevel = 'prep_draft',
  totalKgCo2e = 0,
}) => {
  const { t, locale, setLocale } = useAppTranslation();
  const queryClient = useQueryClient();
  const supplierQuery = useSupplierCarbonScoresQuery(10);
  const schedulesQuery = useQuery({
    queryKey: queryKeys.platform.scheduledReports,
    queryFn: async () => {
      const response = await ApiService.getScheduledReports();
      return ((response as { data?: unknown[] })?.data || []) as Record<string, unknown>[];
    },
    staleTime: 60 * 1000,
  });

  const [scheduleFrequency, setScheduleFrequency] = useState('weekly');
  const [scheduleEmail, setScheduleEmail] = useState('');
  const [scheduleSaving, setScheduleSaving] = useState(false);
  const [whatsappLoading, setWhatsappLoading] = useState(false);
  const [feedback, setFeedback] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const schedules = (schedulesQuery.data || []) as ScheduledReportRow[];
  const [scheduleActionId, setScheduleActionId] = useState<string | null>(null);

  const supplierData = (supplierQuery.data || null) as SupplierScoresPayload | null;
  const suppliers = supplierData?.suppliers || [];

  const [inviteOpen, setInviteOpen] = useState(false);
  const [inviteVendor, setInviteVendor] = useState('');
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteName, setInviteName] = useState('');
  const [inviteMessage, setInviteMessage] = useState('');
  const [inviteSupplierId, setInviteSupplierId] = useState<string | undefined>();
  const [inviteSaving, setInviteSaving] = useState(false);
  const [lastInviteUrl, setLastInviteUrl] = useState<string | null>(null);

  const openInvite = (row?: SupplierScoreRow) => {
    setInviteVendor(row?.vendor || '');
    setInviteEmail(row?.contactEmail || '');
    setInviteName('');
    setInviteMessage('');
    setInviteSupplierId(row?.supplierProfileId || undefined);
    setLastInviteUrl(null);
    setInviteOpen(true);
  };

  const handleSendInvite = async () => {
    setInviteSaving(true);
    setError(null);
    setFeedback(null);
    try {
      const response = await ApiService.inviteUpstreamSupplier({
        vendorName: inviteVendor.trim(),
        contactEmail: inviteEmail.trim(),
        contactName: inviteName.trim() || undefined,
        inviteMessage: inviteMessage.trim() || undefined,
        supplierId: inviteSupplierId,
      });
      if (!response?.success) {
        throw new Error(response?.message || 'Failed to send invite');
      }
      const payload = (response.data || {}) as { inviteUrl?: string; emailSent?: boolean };
      setLastInviteUrl(payload.inviteUrl || null);
      setFeedback(
        payload.emailSent
          ? `Enrollment invite emailed to ${inviteEmail.trim()}.`
          : 'Invite created — copy the link and share it with your supplier.'
      );
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.supplierScores });
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to invite supplier.');
    } finally {
      setInviteSaving(false);
    }
  };

  const handleCopyInvite = async () => {
    if (!lastInviteUrl) return;
    try {
      await navigator.clipboard.writeText(lastInviteUrl);
      setFeedback('Invite link copied.');
    } catch {
      setFeedback(lastInviteUrl);
    }
  };

  const handleWhatsAppShare = async () => {
    setWhatsappLoading(true);
    setError(null);
    setFeedback(null);
    try {
      const response = await ApiService.buildWhatsAppSharePayload({
        reportType,
        period,
        readinessLevel: readinessLevel || 'prep_draft',
        totalKgCo2e,
      });
      const payload = (response as { data?: { whatsappUrl?: string; enabled?: boolean } })?.data;
      if (!payload?.enabled) {
        setError('WhatsApp sharing is disabled on this environment.');
        return;
      }
      if (payload.whatsappUrl) {
        window.open(payload.whatsappUrl, '_blank', 'noopener,noreferrer');
        setFeedback('WhatsApp share opened — review the message before sending.');
      }
    } catch (e) {
      setError(e instanceof Error ? e.message : 'WhatsApp share failed.');
    } finally {
      setWhatsappLoading(false);
    }
  };

  const handleCreateSchedule = async () => {
    setScheduleSaving(true);
    setError(null);
    setFeedback(null);
    try {
      const recipients = scheduleEmail.trim() ? [scheduleEmail.trim()] : undefined;
      await ApiService.createScheduledReport({
        reportType,
        format: 'pdf',
        frequency: scheduleFrequency,
        recipients,
        subject: `Scheduled ${reportType.toUpperCase()} report`,
      });
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback('Scheduled report delivery saved.');
      setScheduleEmail('');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to save schedule.');
    } finally {
      setScheduleSaving(false);
    }
  };

  const handleToggleSchedule = async (schedule: ScheduledReportRow) => {
    setScheduleActionId(schedule._id);
    setError(null);
    try {
      await ApiService.updateScheduledReport(schedule._id, { enabled: !schedule.enabled });
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback(schedule.enabled ? 'Schedule paused.' : 'Schedule resumed.');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to update schedule.');
    } finally {
      setScheduleActionId(null);
    }
  };

  const handleDeleteSchedule = async (scheduleId: string) => {
    setScheduleActionId(scheduleId);
    setError(null);
    try {
      await ApiService.deleteScheduledReport(scheduleId);
      await queryClient.invalidateQueries({ queryKey: queryKeys.platform.scheduledReports });
      setFeedback('Schedule removed.');
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Failed to delete schedule.');
    } finally {
      setScheduleActionId(null);
    }
  };

  const formatScheduleDate = (value?: string) => {
    if (!value) return '—';
    return new Date(value).toLocaleString('en-IN', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <Card variant="outlined" sx={{ mb: 3 }}>
      <CardContent>
        <Stack spacing={2}>
          <Box>
            <Stack direction="row" justifyContent="space-between" alignItems="flex-start" flexWrap="wrap" gap={1}>
              <Box>
                <Typography variant="subtitle1" fontWeight={700} gutterBottom>
                  {t('reporting.shareDelivery')}
                </Typography>
                <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 760 }}>
                  Share a draft summary with buyers, score suppliers, request enrollment for primary-data scores, or schedule recurring PDF delivery.
                </Typography>
              </Box>
              <FormControl size="small" sx={{ minWidth: 120 }}>
                <InputLabel>{t('common.language')}</InputLabel>
                <Select
                  value={locale}
                  label={t('common.language')}
                  onChange={(e) => setLocale(e.target.value as 'en' | 'hi')}
                >
                  <MenuItem value="en">English</MenuItem>
                  <MenuItem value="hi">हिंदी</MenuItem>
                </Select>
              </FormControl>
            </Stack>
          </Box>

          {feedback ? <Alert severity="success">{feedback}</Alert> : null}
          {error ? <Alert severity="error">{error}</Alert> : null}

          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} flexWrap="wrap" useFlexGap>
            <Button
              variant="outlined"
              startIcon={whatsappLoading ? <CircularProgress size={16} /> : <ShareIcon />}
              disabled={whatsappLoading}
              onClick={() => void handleWhatsAppShare()}
            >
              {t('common.shareWhatsApp')}
            </Button>
            <Button
              variant="contained"
              startIcon={<PersonAddAltIcon />}
              onClick={() => openInvite()}
            >
              Request supplier enroll
            </Button>
          </Stack>

          <Box>
            <Stack direction="row" justifyContent="space-between" alignItems="center" flexWrap="wrap" gap={1} sx={{ mb: 1 }}>
              <Typography variant="subtitle2">
                Supplier carbon scores
              </Typography>
              {(supplierData?.enrolledCount || supplierData?.invitedCount) ? (
                <Typography variant="caption" color="text.secondary">
                  {supplierData.enrolledCount || 0} enrolled · {supplierData.invitedCount || 0} invited
                </Typography>
              ) : null}
            </Stack>
            {supplierQuery.isLoading ? (
              <CircularProgress size={20} />
            ) : suppliers.length === 0 ? (
              <Typography variant="body2" color="text.secondary">
                No supplier spend data yet — import purchases or register upstream suppliers, then request enrollment for a primary-data score.
              </Typography>
            ) : (
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Supplier</TableCell>
                      <TableCell>Band</TableCell>
                      <TableCell>Enrollment</TableCell>
                      <TableCell align="right">Intensity</TableCell>
                      <TableCell align="right">Tier-1 data</TableCell>
                      <TableCell align="right">Action</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {suppliers.slice(0, 8).map((row) => (
                      <TableRow key={row.vendor}>
                        <TableCell>
                          <Typography variant="body2">{row.vendor}</Typography>
                          {row.recommendation ? (
                            <Typography variant="caption" color="text.secondary" display="block">
                              {row.recommendation}
                            </Typography>
                          ) : null}
                        </TableCell>
                        <TableCell>
                          <Chip size="small" label={row.scoreBand} color={['A', 'B'].includes(row.scoreBand) ? 'success' : 'warning'} />
                        </TableCell>
                        <TableCell>
                          <Chip
                            size="small"
                            variant="outlined"
                            color={enrollmentChipColor(row.enrollmentStatus)}
                            label={(row.enrollmentStatus || 'not_invited').replace(/_/g, ' ')}
                          />
                        </TableCell>
                        <TableCell align="right">{row.intensityKgCo2ePerInr.toFixed(4)}</TableCell>
                        <TableCell align="right">{Math.round((row.tier1DataRatio || 0) * 100)}%</TableCell>
                        <TableCell align="right">
                          {row.canInvite !== false ? (
                            <Button size="small" onClick={() => openInvite(row)}>
                              Request enroll
                            </Button>
                          ) : (
                            <Typography variant="caption" color="success.main">Enrolled</Typography>
                          )}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            )}
          </Box>

          <Box>
            <Typography variant="subtitle2" gutterBottom>
              Scheduled PDF delivery
            </Typography>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }} useFlexGap>
              <FormControl size="small" sx={{ minWidth: 140 }}>
                <InputLabel>Frequency</InputLabel>
                <Select
                  value={scheduleFrequency}
                  label="Frequency"
                  onChange={(e) => setScheduleFrequency(e.target.value)}
                >
                  <MenuItem value="daily">Daily</MenuItem>
                  <MenuItem value="weekly">Weekly</MenuItem>
                  <MenuItem value="monthly">Monthly</MenuItem>
                </Select>
              </FormControl>
              <TextField
                size="small"
                label="Recipient email (optional)"
                value={scheduleEmail}
                onChange={(e) => setScheduleEmail(e.target.value)}
                sx={{ minWidth: 220 }}
              />
              <Button
                variant="contained"
                startIcon={scheduleSaving ? <CircularProgress size={16} color="inherit" /> : <ScheduleIcon />}
                disabled={scheduleSaving}
                onClick={() => void handleCreateSchedule()}
              >
                Save schedule
              </Button>
            </Stack>
            {schedules.length > 0 ? (
              <TableContainer sx={{ mt: 1 }}>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Report</TableCell>
                      <TableCell>Frequency</TableCell>
                      <TableCell>Next run</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell align="right">Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {schedules.map((schedule) => (
                      <TableRow key={schedule._id}>
                        <TableCell>{String(schedule.reportType || 'brsr').toUpperCase()} · {schedule.format || 'pdf'}</TableCell>
                        <TableCell>{schedule.frequency || 'weekly'}</TableCell>
                        <TableCell>{formatScheduleDate(schedule.nextRunAt)}</TableCell>
                        <TableCell>
                          <Chip
                            size="small"
                            label={schedule.enabled === false ? 'Paused' : schedule.lastStatus || 'Active'}
                            color={schedule.enabled === false ? 'default' : 'success'}
                          />
                        </TableCell>
                        <TableCell align="right">
                          <Stack direction="row" spacing={0.5} justifyContent="flex-end">
                            <Button
                              size="small"
                              disabled={scheduleActionId === schedule._id}
                              onClick={() => void handleToggleSchedule(schedule)}
                            >
                              {schedule.enabled === false ? 'Resume' : 'Pause'}
                            </Button>
                            <Button
                              size="small"
                              color="error"
                              startIcon={<DeleteOutlineIcon fontSize="small" />}
                              disabled={scheduleActionId === schedule._id}
                              onClick={() => void handleDeleteSchedule(schedule._id)}
                            >
                              Delete
                            </Button>
                          </Stack>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </TableContainer>
            ) : (
              <Typography variant="caption" color="text.secondary" display="block" sx={{ mt: 1 }}>
                No schedules yet — save one above to receive recurring PDF delivery.
              </Typography>
            )}
          </Box>
        </Stack>
      </CardContent>

      <Dialog open={inviteOpen} onClose={() => setInviteOpen(false)} fullWidth maxWidth="sm">
        <DialogTitle>Request supplier to enroll</DialogTitle>
        <DialogContent>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Send an invite so the supplier creates a Sustainow account. After enrollment, primary emission data can improve their score band.
          </Typography>
          <Stack spacing={1.5} sx={{ pt: 0.5 }}>
            <TextField
              label="Supplier name"
              value={inviteVendor}
              onChange={(e) => setInviteVendor(e.target.value)}
              fullWidth
              required
            />
            <TextField
              label="Supplier email"
              type="email"
              value={inviteEmail}
              onChange={(e) => setInviteEmail(e.target.value)}
              fullWidth
              required
            />
            <TextField
              label="Contact name (optional)"
              value={inviteName}
              onChange={(e) => setInviteName(e.target.value)}
              fullWidth
            />
            <TextField
              label="Message (optional)"
              value={inviteMessage}
              onChange={(e) => setInviteMessage(e.target.value)}
              fullWidth
              multiline
              minRows={2}
            />
            {lastInviteUrl ? (
              <Alert
                severity="success"
                action={(
                  <Button color="inherit" size="small" startIcon={<ContentCopyIcon />} onClick={() => void handleCopyInvite()}>
                    Copy link
                  </Button>
                )}
              >
                Invite ready. Share this link if email was not delivered.
              </Alert>
            ) : null}
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setInviteOpen(false)}>Close</Button>
          <Button
            variant="contained"
            disabled={inviteSaving || !inviteVendor.trim() || !inviteEmail.trim()}
            onClick={() => void handleSendInvite()}
          >
            {inviteSaving ? 'Sending…' : 'Send enroll request'}
          </Button>
        </DialogActions>
      </Dialog>
    </Card>
  );
};

export default ReportingPlatformPanel;
